"""Compare screen keying against pixels generated by Blender's actual CPU compositor."""
import json
import sys
import unittest
from pathlib import Path
from PIL import Image, ImageChops

sys.path.insert(0, str(Path(__file__).resolve().parents[1]/'backend'))
from screen_keying import screen_key, validate_options

FIXTURE = json.loads((Path(__file__).parent/'fixtures/keying-reference.json').read_text())
NAMES = {'Key Balance':'screen_balance', 'Black Level':'black_level', 'White Level':'white_level',
         'Edge Search Size':'edge_size', 'Edge Tolerance':'edge_tolerance',
         'Despill Strength':'despill_strength', 'Despill Balance':'despill_balance'}


def source_image():
    colors=FIXTURE['source_colors']
    image=Image.new('RGBA',(len(colors)*FIXTURE['block_width'],FIXTURE['height']))
    image.putdata([tuple(color) for _ in range(image.height) for color in colors for _ in range(FIXTURE['block_width'])])
    return image


def encoded(value):
    value=max(0,min(1,value))
    return round(255*(12.92*value if value<=.0031308 else 1.055*value**(1/2.4)-.055))


class ScreenKeyingTests(unittest.TestCase):
    def test_real_blender_reference_for_all_channel_orders_alpha_balances_and_clipping(self):
        image=source_image()
        self.assertTrue(FIXTURE['blender'])
        self.assertEqual(FIXTURE['color_space'], 'scene-linear sRGB')
        for case in FIXTURE['cases']:
            with self.subTest(case=case['name']):
                options={NAMES[name]:value for name,value in case['inputs'].items()}
                rgb,matte=screen_key(image,[case['key']],options,lambda:None,lambda *_:None)
                alpha=ImageChops.multiply(matte,image.getchannel('A'))
                for sample in case['samples']:
                    point=(sample['x'],sample['y']);linear=sample['linear_rgba']
                    expected=[encoded(value/linear[3]) if linear[3] else 0 for value in linear[:3]]+[round(linear[3]*255)]
                    if not expected[3]:expected[:3]=[0,0,0]
                    actual=list(rgb.getpixel(point))+[alpha.getpixel(point)]
                    if not actual[3]:actual[:3]=[0,0,0]
                    self.assertLessEqual(max(abs(a-b) for a,b in zip(actual,expected)),1,(case['name'],point,actual,expected))

    def test_tiles_have_no_seams_in_matte_or_despill_with_edge_aware_clipping(self):
        image=source_image().rotate(90,expand=True)
        options={'black_level':.07,'white_level':.85,'edge_size':3,'edge_tolerance':.1}
        expected=screen_key(image,[[0,255,0]],options,lambda:None,lambda *_:None,tile_height=1000)
        for height in [1,3,7,16]:
            actual=screen_key(image,[[0,255,0]],options,lambda:None,lambda *_:None,tile_height=height)
            self.assertEqual(actual[0].tobytes(),expected[0].tobytes())
            self.assertEqual(actual[1].tobytes(),expected[1].tobytes())

    def test_zero_despill_preserves_source_rgb_and_defaults_keep_a_soft_matte(self):
        image=source_image()
        rgb,matte=screen_key(image,[[0,255,0]],{'despill_strength':0},lambda:None,lambda *_:None)
        self.assertEqual(rgb.tobytes(),image.convert('RGB').tobytes())
        self.assertTrue(any(0<value<255 for value in matte.tobytes()))

    def test_invalid_settings_and_cancellation_fail_before_a_result_is_committed(self):
        for settings in [{'screen_balance':True},{'despill_strength':float('nan')},{'edge_size':9},
                         {'edge_tolerance':-1},{'black_level':.9,'white_level':.8},{'connected_only':1},{'unknown':1}]:
            with self.subTest(settings=settings),self.assertRaises(ValueError):validate_options(settings)
        def cancelled():raise RuntimeError('cancelled')
        with self.assertRaisesRegex(RuntimeError,'cancelled'):
            screen_key(source_image(),[[0,255,0]],None,cancelled,lambda *_:None)
